const MAX_LENGTH = 256;
const MAX_SAFE_BUILD_LENGTH = MAX_LENGTH - 6;
const MAX_SAFE_INT = Number.MAX_SAFE_INTEGER;
const LETTERDASHNUMBER = '[a-zA-Z0-9-]';

const safeRegexReplacements: [string, number][] = [
  ['\\s', 1],
  ['\\d', MAX_LENGTH],
  [LETTERDASHNUMBER, MAX_SAFE_BUILD_LENGTH],
];

function makeSafeRegex(value: string): string {
  for (const [token, max] of safeRegexReplacements) {
    value = value
      .split(`${token}*`).join(`${token}{0,${max}}`)
      .split(`${token}+`).join(`${token}{1,${max}}`);
  }
  return value;
}

const src: { [k: string]: string } = {};
const re: { [k: string]: RegExp } = {};

function createToken(name: string, value: string, isGlobal?: boolean): void {
  src[name] = value;
  re[name] = new RegExp(makeSafeRegex(value), isGlobal ? 'g' : undefined);
}

createToken('NUMERICIDENTIFIER', '0|[1-9]\\d*');
createToken('NUMERICIDENTIFIERLOOSE', '\\d+');
createToken('NONNUMERICIDENTIFIER', `\\d*[a-zA-Z-]${LETTERDASHNUMBER}*`);
createToken('MAINVERSION',
  `(${src.NUMERICIDENTIFIER})\\.` +
  `(${src.NUMERICIDENTIFIER})\\.` +
  `(${src.NUMERICIDENTIFIER})`);
createToken('MAINVERSIONLOOSE',
  `(${src.NUMERICIDENTIFIERLOOSE})\\.` +
  `(${src.NUMERICIDENTIFIERLOOSE})\\.` +
  `(${src.NUMERICIDENTIFIERLOOSE})`);
createToken('PRERELEASEIDENTIFIER',
  `(?:${src.NONNUMERICIDENTIFIER}|${src.NUMERICIDENTIFIER})`);
createToken('PRERELEASEIDENTIFIERLOOSE',
  `(?:${src.NONNUMERICIDENTIFIER}|${src.NUMERICIDENTIFIERLOOSE})`);
createToken('PRERELEASE',
  `(?:-(${src.PRERELEASEIDENTIFIER}(?:\\.${src.PRERELEASEIDENTIFIER})*))`);
createToken('PRERELEASELOOSE',
  `(?:-?(${src.PRERELEASEIDENTIFIERLOOSE}(?:\\.${src.PRERELEASEIDENTIFIERLOOSE})*))`);
createToken('BUILDIDENTIFIER', `${LETTERDASHNUMBER}+`);
createToken('BUILD',
  `(?:\\+(${src.BUILDIDENTIFIER}(?:\\.${src.BUILDIDENTIFIER})*))`);
createToken('FULLPLAIN',
  `v?${src.MAINVERSION}${src.PRERELEASE}?${src.BUILD}?`);
createToken('FULL', `^${src.FULLPLAIN}$`);
createToken('LOOSEPLAIN',
  `[v=\\s]*${src.MAINVERSIONLOOSE}${src.PRERELEASELOOSE}?${src.BUILD}?`);
createToken('GTLT', '((?:<|>)?=?)');
createToken('XRANGEIDENTIFIER', `${src.NUMERICIDENTIFIER}|x|X|\\*`);
createToken('XRANGEPLAIN',
  `[v=\\s]*(${src.XRANGEIDENTIFIER})` +
  `(?:\\.(${src.XRANGEIDENTIFIER})` +
  `(?:\\.(${src.XRANGEIDENTIFIER})` +
  `(?:${src.PRERELEASE})?${src.BUILD}?` +
  `)?)?`);
createToken('XRANGE', `^${src.GTLT}\\s*${src.XRANGEPLAIN}$`);
createToken('LONETILDE', '(?:~>?)');
createToken('TILDETRIM', `(\\s*)${src.LONETILDE}\\s+`, true);
createToken('TILDE', `^${src.LONETILDE}${src.XRANGEPLAIN}$`);
createToken('LONECARET', '(?:\\^)');
createToken('CARETTRIM', `(\\s*)${src.LONECARET}\\s+`, true);
createToken('CARET', `^${src.LONECARET}${src.XRANGEPLAIN}$`);
createToken('COMPARATOR', `^${src.GTLT}\\s*(${src.FULLPLAIN})$|^$`);
createToken('COMPARATORTRIM',
  `(\\s*)${src.GTLT}\\s*(${src.LOOSEPLAIN}|${src.XRANGEPLAIN})`, true);
createToken('HYPHENRANGE',
  `^\\s*(${src.XRANGEPLAIN})` +
  `\\s+-\\s+` +
  `(${src.XRANGEPLAIN})` +
  `\\s*$`);
createToken('STAR', '(<|>)?=?\\s*\\*');
createToken('GTE0', '^\\s*>=\\s*0\\.0\\.0\\s*$');

function isX(id: any): boolean {
  return !id || String(id).toLowerCase() === 'x' || id === '*';
}

function hyphenReplace(...a: any[]): string {
  let from: string = a[1];
  const fM = a[2], fm = a[3], fp = a[4], fpr = a[5];
  let to: string = a[7];
  const tM = a[8], tm = a[9], tp = a[10], tpr = a[11];

  if (isX(fM)) {
    from = '';
  } else if (isX(fm)) {
    from = `>=${fM}.0.0`;
  } else if (isX(fp)) {
    from = `>=${fM}.${fm}.0`;
  } else if (fpr) {
    from = `>=${from}`;
  } else {
    from = `>=${from}`;
  }

  if (isX(tM)) {
    to = '';
  } else if (isX(tm)) {
    to = `<${+tM + 1}.0.0-0`;
  } else if (isX(tp)) {
    to = `<${tM}.${+tm + 1}.0-0`;
  } else if (tpr) {
    to = `<=${tM}.${tm}.${tp}-${tpr}`;
  } else {
    to = `<=${to}`;
  }

  return `${from} ${to}`.trim();
}

function replaceCaret(comp: string): string {
  return comp.replace(re.CARET, (...a: any[]): string => {
    const M = a[1], m = a[2], p = a[3], pr = a[4];
    let ret: string;
    if (isX(M)) {
      ret = '';
    } else if (isX(m)) {
      ret = `>=${M}.0.0 <${+M + 1}.0.0-0`;
    } else if (isX(p)) {
      if (M === '0') {
        ret = `>=${M}.${m}.0 <${M}.${+m + 1}.0-0`;
      } else {
        ret = `>=${M}.${m}.0 <${+M + 1}.0.0-0`;
      }
    } else if (pr) {
      if (M === '0') {
        if (m === '0') {
          ret = `>=${M}.${m}.${p}-${pr} <${M}.${m}.${+p + 1}-0`;
        } else {
          ret = `>=${M}.${m}.${p}-${pr} <${M}.${+m + 1}.0-0`;
        }
      } else {
        ret = `>=${M}.${m}.${p}-${pr} <${+M + 1}.0.0-0`;
      }
    } else {
      if (M === '0') {
        if (m === '0') {
          ret = `>=${M}.${m}.${p} <${M}.${m}.${+p + 1}-0`;
        } else {
          ret = `>=${M}.${m}.${p} <${M}.${+m + 1}.0-0`;
        }
      } else {
        ret = `>=${M}.${m}.${p} <${+M + 1}.0.0-0`;
      }
    }
    return ret;
  });
}

function replaceCarets(comp: string): string {
  return comp.trim().split(/\s+/).map(replaceCaret).join(' ');
}

function replaceTilde(comp: string): string {
  return comp.replace(re.TILDE, (...a: any[]): string => {
    const M = a[1], m = a[2], p = a[3], pr = a[4];
    let ret: string;
    if (isX(M)) {
      ret = '';
    } else if (isX(m)) {
      ret = `>=${M}.0.0 <${+M + 1}.0.0-0`;
    } else if (isX(p)) {
      ret = `>=${M}.${m}.0 <${M}.${+m + 1}.0-0`;
    } else if (pr) {
      ret = `>=${M}.${m}.${p}-${pr} <${M}.${+m + 1}.0-0`;
    } else {
      ret = `>=${M}.${m}.${p} <${M}.${+m + 1}.0-0`;
    }
    return ret;
  });
}

function replaceTildes(comp: string): string {
  return comp.trim().split(/\s+/).map(replaceTilde).join(' ');
}

function replaceXRange(comp: string): string {
  comp = comp.trim();
  return comp.replace(re.XRANGE, (...a: any[]): string => {
    let ret: string = a[0];
    let gtlt: string = a[1];
    let M: any = a[2], m: any = a[3], p: any = a[4];
    const xM = isX(M);
    const xm = xM || isX(m);
    const xp = xm || isX(p);
    const anyX = xp;

    if (gtlt === '=' && anyX) {
      gtlt = '';
    }

    let pr = '';

    if (xM) {
      if (gtlt === '>' || gtlt === '<') {
        ret = '<0.0.0-0';
      } else {
        ret = '*';
      }
    } else if (gtlt && anyX) {
      if (xm) {
        m = 0;
      }
      p = 0;

      if (gtlt === '>') {
        gtlt = '>=';
        if (xm) {
          M = +M + 1;
          m = 0;
          p = 0;
        } else {
          m = +m + 1;
          p = 0;
        }
      } else if (gtlt === '<=') {
        gtlt = '<';
        if (xm) {
          M = +M + 1;
        } else {
          m = +m + 1;
        }
      }

      if (gtlt === '<') {
        pr = '-0';
      }

      ret = `${gtlt + M}.${m}.${p}${pr}`;
    } else if (xm) {
      ret = `>=${M}.0.0${pr} <${+M + 1}.0.0-0`;
    } else if (xp) {
      ret = `>=${M}.${m}.0${pr} <${M}.${+m + 1}.0-0`;
    }

    return ret;
  });
}

function replaceXRanges(comp: string): string {
  return comp.split(/\s+/).map(replaceXRange).join(' ');
}

function replaceStars(comp: string): string {
  return comp.trim().replace(re.STAR, '');
}

function replaceGTE0(comp: string): string {
  return comp.trim().replace(re.GTE0, '');
}

function parseComparator(comp: string): string {
  comp = comp.replace(re.BUILD, '');
  comp = replaceCarets(comp);
  comp = replaceTildes(comp);
  comp = replaceXRanges(comp);
  comp = replaceStars(comp);
  return comp;
}

function semverVersion(version: string): string {
  if (version.length > MAX_LENGTH) {
    throw new TypeError('version is longer than ' + MAX_LENGTH + ' characters');
  }
  const m = version.trim().match(re.FULL);
  if (!m) {
    throw new TypeError('Invalid Version: ' + version);
  }
  const major = +m[1];
  const minor = +m[2];
  const patch = +m[3];
  if (major > MAX_SAFE_INT || major < 0) throw new TypeError('Invalid major version');
  if (minor > MAX_SAFE_INT || minor < 0) throw new TypeError('Invalid minor version');
  if (patch > MAX_SAFE_INT || patch < 0) throw new TypeError('Invalid patch version');

  let prerelease: (string | number)[] = [];
  if (m[4]) {
    prerelease = m[4].split('.').map((id: string): string | number => {
      if (/^[0-9]+$/.test(id)) {
        const num = +id;
        if (num >= 0 && num < MAX_SAFE_INT) {
          return num;
        }
      }
      return id;
    });
  }
  let v = `${major}.${minor}.${patch}`;
  if (prerelease.length) {
    v += `-${prerelease.join('.')}`;
  }
  return v;
}

function comparatorValue(comp: string): string {
  comp = comp.trim().split(/\s+/).join(' ');
  const m = comp.match(re.COMPARATOR);
  if (!m) {
    throw new TypeError('Invalid comparator: ' + comp);
  }
  let operator = m[1] !== undefined ? m[1] : '';
  if (operator === '=') {
    operator = '';
  }
  if (!m[2]) {
    return '';
  }
  return operator + semverVersion(m[2]);
}

const NULL_SET = '<0.0.0-0';

function parseRange(range: string): string[] {
  range = range.replace(re.HYPHENRANGE, hyphenReplace);
  range = range.replace(re.COMPARATORTRIM, '$1$2$3');
  range = range.replace(re.TILDETRIM, '$1~');
  range = range.replace(re.CARETTRIM, '$1^');

  const rangeList = range
    .split(' ')
    .map(parseComparator)
    .join(' ')
    .split(/\s+/)
    .map(replaceGTE0);

  const comparators = rangeList.map(comparatorValue);
  const rangeMap = new Map<string, string>();
  for (const value of comparators) {
    if (value === NULL_SET) {
      return [value];
    }
    rangeMap.set(value, value);
  }
  if (rangeMap.size > 1 && rangeMap.has('')) {
    rangeMap.delete('');
  }
  const result: string[] = [];
  rangeMap.forEach((v) => {
    result.push(v);
  });
  return result;
}

function formatRange(input: string): string {
  const raw = input.trim().replace(/\s+/g, ' ');

  let set: string[][] = raw
    .split('||')
    .map((r) => parseRange(r.trim()))
    .filter((c) => c.length > 0);

  if (!set.length) {
    throw new TypeError('Invalid SemVer Range: ' + raw);
  }

  if (set.length > 1) {
    const first = set[0];
    set = set.filter((c) => c[0] !== NULL_SET);
    if (set.length === 0) {
      set = [first];
    } else if (set.length > 1) {
      for (const c of set) {
        if (c.length === 1 && c[0] === '') {
          set = [c];
          break;
        }
      }
    }
  }

  let formatted = '';
  for (let i = 0; i < set.length; i++) {
    if (i > 0) {
      formatted += '||';
    }
    const comps = set[i];
    for (let k = 0; k < comps.length; k++) {
      if (k > 0) {
        formatted += ' ';
      }
      formatted += comps[k].trim();
    }
  }
  return formatted;
}

export function solve(range: string): string | null {
  try {
    if (typeof range !== 'string') {
      return null;
    }
    return formatRange(range) || '*';
  } catch (e) {
    return null;
  }
}
